Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
tee: shm: fix shm leak in register_shm_helper()

register_shm_helper() allocates shm before calling
iov_iter_npages(). If iov_iter_npages() returns 0, the function
jumps to err_ctx_put and leaks shm.

This can be triggered by TEE_IOC_SHM_REGISTER with
struct tee_ioctl_shm_register_data where length is 0.

Jump to err_free_shm instead.

Fixes: 7bdee4157591 ("tee: Use iov_iter to better support shared buffer registration")
Cc: stable@vger.kernel.org
Cc: lvc-project@linuxtesting.org
Signed-off-by: Georgiy Osokin <g.osokin@auroraos.dev>
Reviewed-by: Sumit Garg <sumit.garg@oss.qualcomm.com>
Signed-off-by: Jens Wiklander <jens.wiklander@linaro.org>

Here is the root cause:
The function `register_shm_helper()` allocates memory for `shm` before calling `iov_iter_npages()`. When `iov_iter_npages()` returns 0 (e.g., due to a zero-length input), the error path incorrectly jumps to `err_ctx_put`, which only releases the context reference but does not free the previously allocated `shm`, causing a memory leak. The fix changes the jump target to `err_free_shm`, which properly deallocates `shm`.

Here is the patch:

 static struct tee_shm *
 register_shm_helper(struct tee_context *ctx, struct iov_iter *iter, u32 flags,
 		    int id)
 {
 	struct tee_device *teedev = ctx->teedev;
 	struct tee_shm *shm;
 	unsigned long start, addr;
 	size_t num_pages, off;
 	ssize_t len;
 	void *ret;
 	int rc;

 	if (!tee_device_get(teedev))
 		return ERR_PTR(-EINVAL);

 	if (!teedev->desc->ops->shm_register ||
 	    !teedev->desc->ops->shm_unregister) {
 		ret = ERR_PTR(-ENOTSUPP);
 		goto err_dev_put;
 	}

 	teedev_ctx_get(ctx);

 	shm = kzalloc_obj(*shm);
 	if (!shm) {
 		ret = ERR_PTR(-ENOMEM);
 		goto err_ctx_put;
 	}

 	refcount_set(&shm->refcount, 1);
 	shm->flags = flags;
 	shm->ctx = ctx;
 	shm->id = id;
 	addr = untagged_addr((unsigned long)iter_iov_addr(iter));
 	start = rounddown(addr, PAGE_SIZE);
 	num_pages = iov_iter_npages(iter, INT_MAX);
 	if (!num_pages) {
 		ret = ERR_PTR(-ENOMEM);
-		goto err_ctx_put;
+		goto err_free_shm;
 	}

 	shm->pages = kzalloc_objs(*shm->pages, num_pages);
 	if (!shm->pages) {
 		ret = ERR_PTR(-ENOMEM);
 		goto err_free_shm;
 	}

 	len = iov_iter_extract_pages(iter, &shm->pages, LONG_MAX, num_pages, 0,
 				     &off);
 	if (unlikely(len <= 0)) {
 		ret = len ? ERR_PTR(len) : ERR_PTR(-ENOMEM);
 		goto err_free_shm_pages;
 	} else if (DIV_ROUND_UP(len + off, PAGE_SIZE) != num_pages) {
 		/*
 		 * If we only got a few pages, update to release the
 		 * correct amount below.
 		 */
 		shm->num_pages = len / PAGE_SIZE;
 		ret = ERR_PTR(-ENOMEM);
 		goto err_put_shm_pages;
 	}

 	shm->offset = off;
 	shm->size = len;
 	shm->num_pages = num_pages;

 	rc = teedev->desc->ops->shm_register(ctx, shm, shm->pages,
 					     shm->num_pages, start);
 	if (rc) {
 		ret = ERR_PTR(rc);
 		goto err_put_shm_pages;
 	}

 	return shm;
 err_put_shm_pages:
 	if (!iov_iter_is_kvec(iter))
 		unpin_user_pages(shm->pages, shm->num_pages);
 err_free_shm_pages:
 	kfree(shm->pages);
 err_free_shm:
 	kfree(shm);
 err_ctx_put:
 	teedev_ctx_put(ctx);
 err_dev_put:
 	tee_device_put(teedev);
 	return ret;
 }



